
CREATE TEMP TABLE temp_professions
(
    id uuid NOT NULL PRIMARY KEY,
    kzis_code integer NOT NULL,
    kzis_name character varying(255) NOT NULL,
    profession_group_id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NULL,
    created_by_id uuid NOT NULL,
    created_by_name character varying(200) NULL,
    updated_by_id uuid NULL,
    updated_by_name character varying(200) NULL
)
ON COMMIT DROP;
















MERGE INTO prof.professions AS target
USING
(
    SELECT
        temporary_profession.id,
        temporary_profession.kzis_code,
        temporary_profession.kzis_name,
        profession_group.id AS profession_group_id,
        temporary_profession.created_at,
        temporary_profession.updated_at,
        temporary_profession.created_by_id,
        temporary_profession.created_by_name,
        temporary_profession.updated_by_id,
        temporary_profession.updated_by_name
    FROM temp_professions AS temporary_profession
    INNER JOIN prof.profession_groups AS profession_group
        ON profession_group.id =
           temporary_profession.profession_group_id
) AS source
ON target.id = source.id

WHEN MATCHED THEN
    UPDATE SET
        kzis_code = source.kzis_code,
        kzis_name = source.kzis_name,
        profession_group_id = source.profession_group_id,
        updated_at = CURRENT_TIMESTAMP,
        updated_by_id = source.updated_by_id,
        updated_by_name = source.updated_by_name

WHEN NOT MATCHED THEN
    INSERT
    (
        id,
        kzis_code,
        kzis_name,
        profession_group_id,
        created_at,
        updated_at,
        created_by_id,
        created_by_name,
        updated_by_id,
        updated_by_name
    )
    VALUES
    (
        source.id,
        source.kzis_code,
        source.kzis_name,
        source.profession_group_id,
        source.created_at,
        source.updated_at,
        source.created_by_id,
        source.created_by_name,
        source.updated_by_id,
        source.updated_by_name
    );
